  for (let i = block.length - 1; i >= 0; i -= 1) {
    const body = /^"(.*)"$/su.exec(block[i].trim())?.[1] ?? "";
    if (body === "") continue;
    return /(?<!\\)(?:\\\\)*\\n$/u.test(body);
  }
  return false;
};

let changed = 0;
for (const file of process.argv.slice(2)) {
  const lines = readFileSync(file, "utf8").split("\n");
  let field = null;
  let msgidBlock = [];
  let msgstrIndexes = [];

  const flush = () => {
    if (msgstrIndexes.length === 0 || msgidBlock.length === 0) return;
    if (endsWithNewline(msgidBlock)) return;
    for (let i = msgstrIndexes.length - 1; i >= 0; i -= 1) {
      const index = msgstrIndexes[i];
      const match = /^(?<prefix>\s*(?:msgstr )?)"(?<body>.*)"\s*$/su.exec(lines[index]);
      if (!match) return;
      const { prefix, body } = match.groups;
      if (body === "") continue;
      if (!/(?<!\\)(?:\\\\)*\\n$/u.test(body)) return;
      lines[index] = `${prefix}"${body.slice(0, -2)}"`;
      changed += 1;
      return;
    }
  };

  for (const [index, line] of lines.entries()) {
    if (line.startsWith("msgid ")) {
      flush();
      field = "msgid";
      msgidBlock = [line.slice("msgid ".length)];
      msgstrIndexes = [];
    } else if (line.startsWith("msgstr ")) {
      field = "msgstr";
      msgstrIndexes = [index];
    } else if (line.startsWith('"')) {
      if (field === "msgid") msgidBlock.push(line);
      else if (field === "msgstr") msgstrIndexes.push(index);
    } else if (line.trim() === "" || line.startsWith("#")) {
      if (line.trim() === "") {
        flush();
        field = null;
        msgidBlock = [];
        msgstrIndexes = [];
      }
    } else {
      field = null;
    }
  }
  flush();
  writeFileSync(file, lines.join("\n"));
}
